mapper.select:
select t.* from cc_task_config t where t.company_id=#{companyId} and t.archived=0 and t.id > #{afterId}
and (t.status=1 or t.requested_status is not null or exists(select 1 from cc_task_attempt a where a.company_id=#{companyId} and a.task_id=t.id and a.state='claimed'))
order by t.id limit #{limit}

select a.*,c.phone,c.custom_data from cc_task_attempt a join cc_task_contact c on c.id=a.contact_id and c.task_id=a.task_id
where a.company_id=#{companyId} and a.task_id=#{taskId} and a.state='claimed' and a.attempt_id > #{afterAttemptId}
order by a.attempt_id limit #{limit}

mapper.update:
update cc_task_attempt set call_id=#{callId},media_host=#{mediaHost},dispatch_time=#{dispatchTime},uts=#{uts}
where company_id=#{companyId} and task_id=#{taskId} and attempt_id=#{attemptId} and lease_token=#{leaseToken}
  and state='claimed' and call_id is null and lease_until > #{uts}
